video-upload{height:90px;width:240px;border:1px dashed #cbd5e1;border-radius:9px;background:#f8fafc;color:#64748b}.workflow{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.workflow>div{padding:12px;border:1px solid #e2e8f0;border-radius:9px}.workflow>div.active{border-color:#2563eb;background:#eff6ff}.workflow span{display:inline-flex;width:22px;height:22px;align-items:center;justify-content:center;border-radius:50%;background:#e2e8f0;margin-right:7px}.workflow strong{font-size:12px}.workflow small{display:block;margin:7px 0 0 29px;color:#64748b}.sticky-footer{position:fixed;left:var(--sidebar-width,220px);right:0;bottom:0;z-index:10;display:flex;justify-content:space-between;padding:13px 24px;border-top:1px solid #e2e8f0;background:#fff;box-shadow:0 -8px 24px rgba(15,23,42,.05)}@media(max-width:900px){.two-grid,.three-grid{grid-template-columns:1fr}.media-grid{grid-template-columns:repeat(2,1fr)}.sticky-footer{left:0}}
</style>
